vyatta_cfg_run is a function
vyatta_cfg_run () 
{ 
    if [[ "$1" == "set" && "$2" =~ ^(-|\+).* ]]; then
        set "${@:2}";
        return;
    fi;
    local cmd=$1;
    local -a args=("$@");
    local -a filtered_cmds;
    get_prefix_filtered_list $cmd _vyatta_cfg_cmds filtered_cmds;
    local found;
    is_elem_of "${cmd}" _vyatta_cfg_cmds;
    found=$?;
    stty echo 2> /dev/null;
    if [[ "${#filtered_cmds[@]}" == "0" ]]; then
        echo -ne "\n  Invalid command: [$cmd]\n\n" 1>&2;
        return 1;
    else
        if [[ "${#filtered_cmds[@]}" != "1" && "$found" == "1" ]]; then
            echo -ne "\n  Ambiguous command: [$cmd]\n" 1>&2;
            local -a fitems=();
            local -a fstrs=();
            local -a _get_help_text_items=("${_vyatta_cfg_cmds[@]}");
            local -a _get_help_text_helps=("${_vyatta_cfg_helps[@]}");
            get_prefix_filtered_list2 "$cmd" _get_help_text_items fitems _get_help_text_helps fstrs;
            _get_help_text_items=("${fitems[@]}");
            _get_help_text_helps=("${fstrs[@]}");
            get_help_text;
            echo -e "$vyatta_help_text\n" | sed 's/^P/  P/';
            return 1;
        fi;
    fi;
    local fcmd;
    if is_elem_of "${cmd}" _vyatta_cfg_cmds; then
        fcmd=$cmd;
    else
        fcmd=${filtered_cmds[0]};
    fi;
    case $fcmd in 
        compare)
            vyatta_config_compare "${@:2}"
        ;;
        comment)
            vyatta_config_comment "${args[@]}"
        ;;
        copy | rename)
            vyatta_config_copy $fcmd ${@:2}
        ;;
        exit)
            vyatta_config_exit "${@:2}"
        ;;
        run)
            vyatta_config_run "${@:2}"
        ;;
        load)
            vyatta_config_load "${@:2}"
        ;;
        commit)
            vyatta_config_commit "${@:2}"
        ;;
        confirm)
            vyatta_config_confirm "${@:2}"
        ;;
        rollback)
            vyatta_config_rollback "${@:2}"
        ;;
        rollback-soft)
            vyatta_config_rollback-soft "${@:2}"
        ;;
        commit-confirm)
            vyatta_config_commit-confirm "${@:2}"
        ;;
        compare)
            vyatta_config_compare "${@:2}"
        ;;
        save)
            vyatta_config_save "${@:2}"
        ;;
        merge)
            vyatta_config_merge "${@:2}"
        ;;
        *)
            vyatta_cfg_cmd $fcmd "${@:2}"
        ;;
    esac
}
vyatta_configure is a function
vyatta_configure () 
{ 
    session_env=$($API getSessionEnv $PPID);
    eval $session_env;
    $API setupSession;
    echo $session_env
}
